lab.solution:
def import_feedback(code, row_number):
    if code == 'missing_minutes':
        return {'code': code, 'message': f'Row {row_number} has no study minutes. Add a number and try again.'}
    return {'code': 'import_failed', 'message': 'The import could not finish. Try again or share the run ID with support.'}

known = import_feedback('missing_minutes', 3)
assert known['code'] == 'missing_minutes'
assert 'Row 3' in known['message'] and 'try again' in known['message']
assert 'traceback' not in import_feedback('other', 0)['message'].lower()
